import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"UI layers","description":"A UI layer is a package of components that depend on @pidrang/core and their own styling library, never on a DataProvider. Pidrang ships two today —...","frontmatter":{"description":"A UI layer is a package of components that depend on @pidrang/core and their own styling library, never on a DataProvider. Pidrang ships two today —..."},"headers":[],"relativePath":"ui-layers/index.md","filePath":"ui-layers/index.md"}'),d={name:"ui-layers/index.md"};function o(n,e,l,s,c,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="ui-layers" tabindex="-1">UI layers <a class="header-anchor" href="#ui-layers" aria-label="Permalink to &quot;UI layers&quot;">​</a></h1><p>A UI layer is a package of components that depend on <code>@pidrang/core</code> and their own styling library, never on a <code>DataProvider</code>. Pidrang ships two today — Material and Tailwind — and plans a third.</p><h2 id="material-and-tailwind" tabindex="-1">Material and Tailwind <a class="header-anchor" href="#material-and-tailwind" aria-label="Permalink to &quot;Material and Tailwind&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Styling</th><th>What you install</th><th>What the app must configure</th></tr></thead><tbody><tr><td><code>@pidrang/material</code></td><td>Angular Material</td><td><code>@pidrang/material</code> + <code>@angular/material</code> (via <code>ng add @angular/material</code>)</td><td>A <code>mat.theme()</code> call with palette, typography and density; <code>color-scheme: light dark</code> in the root element</td></tr><tr><td><code>@pidrang/tailwind</code></td><td>Tailwind utility classes</td><td><code>@pidrang/tailwind</code> only (app must already have Tailwind v4)</td><td>A <code>@source</code> line pointing at the installed library so its template classes are scanned and generated</td></tr></tbody></table><p>See <a href="./material">Angular Material</a> or <a href="./tailwind">Tailwind CSS</a> for the setup of each one.</p><h2 id="the-same-api" tabindex="-1">The same API <a class="header-anchor" href="#the-same-api" aria-label="Permalink to &quot;The same API&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Material element</th><th>Tailwind element</th></tr></thead><tbody><tr><td><code>ResourceTable&lt;T&gt;</code></td><td><code>pidrang-material-resource-table</code></td><td><code>pidrang-tailwind-resource-table</code></td></tr><tr><td><code>ResourceForm&lt;T&gt;</code></td><td><code>pidrang-material-resource-form</code></td><td><code>pidrang-tailwind-resource-form</code></td></tr></tbody></table><p>Switching between layers is a change of import and element name. See <a href="./../reference/components">Components reference</a> for inputs, outputs and behaviour.</p><h2 id="what-the-generator-writes" tabindex="-1">What the generator writes <a class="header-anchor" href="#what-the-generator-writes" aria-label="Permalink to &quot;What the generator writes&quot;">​</a></h2><p>Three facts about what <code>pidrang init</code> generates:</p><ol><li><strong>Layout and sign-in follow the app&#39;s declared UI layer</strong> — <code>layoutUiOf()</code> checks <code>package.json</code>; if the app declares <code>@pidrang/tailwind</code>, the layout and sign-in page use Tailwind styles, otherwise they use Material. Source: <code>apps/pidrang-cli/src/app-tooling.ts</code> lines 93–101.</li><li><strong>Generated CRUD pages are always Angular Material</strong> — <code>PAGES_UI_LAYER_PACKAGES</code> always installs <code>@pidrang/material</code> and <code>@angular/material</code>, and uses the Material selectors. An app using <code>@pidrang/tailwind</code> still needs Material installed for its generated pages. Source: <code>libs/cli/src/lib/generate-pages-bundle.ts</code> lines 70–73.</li><li>Pages can be replaced — see <a href="./../reference/cli#changing-what-it-wrote">the CLI reference</a>.</li></ol><h2 id="choosing" tabindex="-1">Choosing <a class="header-anchor" href="#choosing" aria-label="Permalink to &quot;Choosing&quot;">​</a></h2><ul><li>Use Material if your application already uses Angular Material.</li><li>Use Tailwind if your application has Tailwind v4 and no component library.</li><li>Both can coexist in one app — they use distinct selectors (<code>pidrang-material-*</code> vs <code>pidrang-tailwind-*</code>).</li></ul><h2 id="a-third-layer" tabindex="-1">A third layer <a class="header-anchor" href="#a-third-layer" aria-label="Permalink to &quot;A third layer&quot;">​</a></h2><p>A third layer, <code>@pidrang/ng-zorro</code>, is planned and implements the same contract.</p>',15)])])}const u=a(d,[["render",o]]);export{g as __pageData,u as default};
